    directions = [(-1,0), (1,0), (0,-1), (0,1)]

    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    def bfs(frontier, came_from, other_frontier, other_came_from):
        while frontier:
            r, c = frontier.popleft()
            for dr, dc in directions:
                nr, nc = r + dr, c + dc
                if is_valid(nr, nc):
                    if (nr, nc) in other_came_from:
                        path = [(nr, nc), (r, c)]
                        while (r, c) in came_from:
                            r, c = came_from[(r, c)]
                            path.insert(0, (r, c))
                        return path
                    if (nr, nc) not in came_from:
                        came_from[(nr, nc)] = (r, c)
                        frontier.append((nr, nc))
        return []

    start_queue = deque([start])
    goal_queue = deque([goal])
    start_came_from = {start: None}
    goal_came_from = {goal: None}

    while start_queue and goal_queue:
        path = bfs(start_queue, start_came_from, goal_queue, goal_came_from)
        if path:
            return path
        path = bfs(goal_queue, goal_came_from, start_queue, start_came_from)
        if path:
            return path
    return []

